import numpy as np
from scipy import stats

MAX_DRIVERS = 5

def design(feats):
    # Calculate effect sizes for all features
    effect_sizes = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] != 'clinical':
            # Use Welch's t-test statistic as proxy for effect size
            t_stat = feats.x[:, i].T @ (feats.y * 2 - 1) / np.sqrt(np.var(feats.x[:, i]) * len(feats.y))
            effect_sizes.append((fid, abs(t_stat), feats.x[:, i].T @ (feats.y * 2 - 1)))

    # Sort by effect size magnitude
    effect_sizes.sort(key=lambda x: x[1], reverse=True)

    # Filter out near-duplicates (correlated features with |r| >= 0.6)
    selected = []
    for fid, _, _ in effect_sizes:
        is_duplicate = False
        for selected_fid in selected:
            col_a = feats.column(selected_fid)
            col_b = feats.column(fid)
            corr = np.corrcoef(feats.x[:, col_a], feats.x[:, col_b])[0, 1]
            if abs(corr) >= 0.6:
                is_duplicate = True
                break
        if not is_duplicate:
            selected.append(fid)

    # Select top features for drivers (at most MAX_DRIVERS)
    drivers = tuple(selected[:MAX_DRIVERS])

    # For columns, use all features except near-duplicates
    columns = tuple(selected)

    # For products, consider pairs of correlated features
    products = []
    for i, fid_a in enumerate(columns):
        for fid_b in columns[i+1:]:
            col_a = feats.column(fid_a)
            col_b = feats.column(fid_b)
            corr = np.corrcoef(feats.x[:, col_a], feats.x[:, col_b])[0, 1]
            if abs(corr) >= 0.6:
                products.append((fid_a, fid_b))

    # Loadings: use effect sizes as weights
    loadings = {}
    for fid, _, effect_size in effect_sizes:
        if fid in columns:
            loadings[fid] = effect_size

    return Design(drivers=drivers, columns=columns, products=tuple(products), loadings=loadings)
